const T eps = std::epsilon<T>();
real3<T> inversed_v;

T x = (std::abs(v.x) < eps) ? T(0) : T(1) / v.x;
T y = (std::abs(v.y) < eps) ? T(0) : T(1) / v.y;
T z = (std::abs(v.z) < eps) ? T(0) : T(1) / v.z;

// Handle x component
if (std::abs(v.x) < eps) {
    if (v.x > 0) {
        x = T(1) / v.x;
    } else {
.        x = T(0);
    }
}

// Handle y component
if (std::abs(v.y) < eps) {
    if (v.y > 0) {
        y = T(1) / v.y;
    } else {
        y = T(0);
    }
}

// Handle z component
if (std::abs(v.z) < eps) {
    if (v.z > 0) {
        z = T(1) / v.z;
    } else {
        z = T(0);
    }
}

// Set the inverted components
inversed_v.x = x;
inversed_v.y = y;
inversed_v.z = z;

return inversed v;

